INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 2, "ペコリーヌとの出会い", 8, 2834, 10118, 1, 5118061, "青空の下で謁見", 91002, 0, "フリーマーケット会場", 40, 20063115, 7);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 2, "マホとの出会い", 8, 2835, 10118, 1, 5118062, "未来の騎空団\nマスコット？", 91002, 0, "フリーマーケット会場", 40, 20063115, 7);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 2, "アキノとの出会い", 8, 2837, 10118, 1, 5118063, "お嬢さまからの\n緊急依頼", 91002, 0, "ランドソル市街地", 40, 20063115, 7);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 2, "ジュンとの出会い", 8, 4108402, 10118, 1, 5118064, "黄金色の悩みごと", 91002, 0, "フリーマーケット会場", 40, 20063115, 18);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 2, "カオリとの出会い", 8, 4107402, 10118, 1, 5118065, "白熱！　格闘大会！", 91002, 0, "フリーマーケット会場", 40, 20063115, 18);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 2, "ニノンとの出会い", 8, 9000227, 10118, 1, 5118066, "祭り太鼓はオーエドの華", 91002, 1, "オーエド町", 40, 20063115, 16);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 3, "スズナとの出会い", 8, 2101181, 10118, 1, 5118067, "人気者は遅れて\nやってくる", 91002, 0, "フリーマーケット会場", 40, 20063115, 19);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 3, "ナナカとの出会い", 8, 4109402, 10118, 1, 5118068, "巫女・ミーツ・魔法少女", 91002, 0, "ランドソル市街地", 40, 20063115, 18);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 3, "キャル＆コッコロとの出会い", 8, 4305402, 10118, 1, 5118069, "ネズ耳は二度なくなる", 91002, 0, "フリーマーケット会場", 40, 20063115, 18);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 3, "ユカリとの出会い", 8, 4101402, 10118, 1, 5118070, "この出会いにカンパイ！", 91002, 0, "ランドソル市街地", 40, 20063115, 18);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 3, "アオイとの出会い", 8, 4106402, 10118, 1, 5118071, "陰陽アンサンブル", 91002, 0, "ランドソル市街地", 40, 20063115, 18);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES ("ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 3, "シノブとの出会い", 8, 2836, 10118, 1, 5118072, "運試し十番勝負！", 91002, 1, "フリーマーケット会場", 40, 20063115, 7);
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (0, 1, "オープニング", 0, 0, 10118, 0, 5118600, "彼女たちの新たな日常", 0, 0, 0, 0, 20063115, 0);
